package com.witchersbestiary.signs;
import java.util.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.entity.*;import net.minecraft.entity.mob.*;import net.minecraft.entity.passive.*;import net.minecraft.entity.effect.*;import net.minecraft.entity.damage.*;import net.minecraft.registry.*;import net.minecraft.registry.tag.DamageTypeTags;import net.minecraft.util.*;import net.minecraft.util.math.*;import net.minecraft.particle.*;import net.minecraft.sound.*;import net.minecraft.text.Text;import net.fabricmc.fabric.api.networking.v1.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;
public final class SignManager {
 public static final RegistryKey<DamageType> DAMAGE=RegistryKey.of(RegistryKeys.DAMAGE_TYPE,Identifier.of("witchersbestiary:sign"));
 private static final Map<UUID,Runtime> ACTIVE=new HashMap<>();private static final Map<UUID,Long> CALM=new HashMap<>();
 private static final class Runtime {UUID session=UUID.randomUUID();long sequence=-1;float shield;int shieldTicks,trapTicks;Vec3d trap;RegistryKey<net.minecraft.world.World> dimension;}
 private static Runtime runtime(ServerPlayerEntity p){return ACTIVE.computeIfAbsent(p.getUuid(),k->new Runtime());}
 public static SignPlayerState state(ServerPlayerEntity p){return SignLedger.get(p.getServer()).player(p.getUuid());}
 public static boolean calmed(LivingEntity e){Long until=CALM.get(e.getUuid());return until!=null&&until>e.getWorld().getTime();}
 public static boolean allowed(ServerPlayerEntity p){return p.isAlive()&&!p.isSpectator()&&!com.witchersbestiary.fist.FistFights.busy(p);}
 public static boolean enemy(ServerPlayerEntity p,LivingEntity e){return e!=p&&e.isAlive()&&!e.isInvulnerable()&&!p.isTeammate(e)&&!com.witchersbestiary.fist.FistFights.busy(e)&&!(e instanceof TameableEntity t&&t.isTamed())&&!(e instanceof VillagerEntity)&&!(e instanceof com.witchersbestiary.merchant.ArcaneMerchant)&&(!(e instanceof com.witchersbestiary.fist.FistNpc)||e instanceof com.witchersbestiary.fist.RockTrollEntity)&&(e instanceof Monster||e instanceof com.witchersbestiary.combat.CategorizedMonster||e instanceof com.witchersbestiary.fist.RockTrollEntity&&e.getAttacker()==p);}
 public static void intent(ServerPlayerEntity p,SignPackets.Intent packet){var r=runtime(p);if(!r.session.equals(packet.session())||packet.sequence()<=r.sequence)return;r.sequence=packet.sequence();var sign=SignType.byIndex(packet.sign());if(packet.action()==0){if(sign!=null&&state(p).select(sign))SignLedger.get(p.getServer()).markDirty();}else if(packet.action()==1)cast(p,packet.sequence());sync(p);}
 public static boolean cast(ServerPlayerEntity p,long request){if(!allowed(p)){p.sendMessage(Text.translatable("sign.witchersbestiary.unavailable"),true);return false;}var s=state(p);var sign=s.selected();var w=p.getServerWorld();var r=runtime(p);var origin=p.getEyePos();var look=p.getRotationVec(1);var targets=w.getEntitiesByClass(LivingEntity.class,p.getBoundingBox().expand(sign.range),e->enemy(p,e)&&p.canSee(e)&&e.getEyePos().distanceTo(origin)<=sign.range&&e.getEyePos().subtract(origin).normalize().dotProduct(look)>=Math.cos(Math.toRadians(sign==SignType.AXII?12:30)));targets.sort(Comparator.comparingDouble(p::squaredDistanceTo));if(sign==SignType.AXII&&(targets.isEmpty()||!(targets.getFirst() instanceof MobEntity)))return false;
 if(sign==SignType.AXII){Long until=CALM.get(targets.getFirst().getUuid());if(until!=null&&until+80>w.getTime())return false;}
 Vec3d trap=p.getPos();if(sign==SignType.YRDEN){var pos=p.getBlockPos();if(!w.isChunkLoaded(pos)||!w.getBlockState(pos).getCollisionShape(w,pos).isEmpty()||!w.getBlockState(pos.down()).isSideSolidFullSquare(w,pos.down(),Direction.UP))return false;}
 if(!s.commit(sign,request))return false;SignLedger.get(p.getServer()).markDirty();r.dimension=w.getRegistryKey();p.swingHand(Hand.OFF_HAND,true);var damage=new DamageSource(w.getRegistryManager().get(RegistryKeys.DAMAGE_TYPE).entryOf(DAMAGE),p);
 switch(sign){case IGNI,AARD->{for(var target:targets.stream().limit(12).toList()){if(sign==SignType.IGNI&&(target.isFireImmune()||target.hasStatusEffect(StatusEffects.FIRE_RESISTANCE)))continue;if(target.damage(damage,sign==SignType.IGNI?4:1)){if(sign==SignType.IGNI&&!target.isFireImmune())target.setOnFireFor(3);if(sign==SignType.AARD){double factor=target.getWidth()>1.5?.3:1;var v=target.getPos().subtract(p.getPos()).normalize().multiply(.85*factor);target.addVelocity(v.x,.18*factor,v.z);target.velocityModified=true;}}}for(int i=1;i<=12;i++){var at=origin.add(look.multiply(i*sign.range/12));w.spawnParticles(sign==SignType.IGNI?ParticleTypes.FLAME:ParticleTypes.CLOUD,at.x,at.y,at.z,2,.12,.12,.12,.015);}}
 case QUEN->{r.shield=8;r.shieldTicks=240;burst(w,p.getPos().add(0,1,0),sign,16);}
 case YRDEN->{r.trap=trap;r.trapTicks=200;r.dimension=w.getRegistryKey();}
 case AXII->{var target=(MobEntity)targets.getFirst();long now=w.getTime();Long until=CALM.get(target.getUuid());if(until==null||until+80<=now){CALM.put(target.getUuid(),now+(target.getWidth()>1.5?30:80));target.setTarget(null);target.getNavigation().stop();burst(w,target.getEyePos(),sign,6);}}
 }w.playSound(null,p.getBlockPos(),switch(sign){case IGNI->SoundEvents.ITEM_FIRECHARGE_USE;case AARD->SoundEvents.ENTITY_BREEZE_SHOOT;case QUEN->SoundEvents.BLOCK_AMETHYST_BLOCK_CHIME;case YRDEN->SoundEvents.BLOCK_AMETHYST_BLOCK_RESONATE;case AXII->SoundEvents.BLOCK_BEACON_AMBIENT;},SoundCategory.PLAYERS,.45f,1.15f);sync(p);return true;}
 private static void burst(ServerWorld w,Vec3d at,SignType sign,int count){int rgb=sign.color;w.spawnParticles(new DustParticleEffect(new org.joml.Vector3f(((rgb>>16)&255)/255f,((rgb>>8)&255)/255f,(rgb&255)/255f),.9f),at.x,at.y,at.z,count,.45,.5,.45,.01);}
 public static float protect(LivingEntity victim,DamageSource source,float amount){if(!(victim instanceof ServerPlayerEntity p)||!allowed(p)||!Float.isFinite(amount)||amount<=0||p.isInvulnerableTo(source)||p.blockedByShield(source)||p.timeUntilRegen>10||source.isIn(DamageTypeTags.BYPASSES_INVULNERABILITY))return amount;var r=runtime(p);if(r.shieldTicks<=0||r.shield<=0)return amount;float taken=Math.min(r.shield,amount);r.shield-=taken;burst(p.getServerWorld(),p.getPos().add(0,1,0),SignType.QUEN,r.shield<=0?12:4);sync(p);return amount-taken;}
 public static void sync(ServerPlayerEntity p){if(!ServerPlayNetworking.canSend(p,SignPackets.View.ID))return;var s=state(p);var r=runtime(p);ServerPlayNetworking.send(p,new SignPackets.View(r.session,s.learned(),s.selected().ordinal(),(float)s.concentration(),s.cooldown(s.selected()),r.shield,r.shieldTicks,r.trapTicks));}
 public static void initialize(){SignPackets.initialize();ServerPlayConnectionEvents.JOIN.register((h,sender,server)->{state(h.player).resetProtocol();ACTIVE.remove(h.player.getUuid());sync(h.player);});ServerPlayConnectionEvents.DISCONNECT.register((h,s)->{ACTIVE.remove(h.player.getUuid());SignLedger.get(s).markDirty();});ServerLifecycleEvents.SERVER_STOPPED.register(s->{ACTIVE.clear();CALM.clear();});ServerTickEvents.END_SERVER_TICK.register(server->{for(var p:server.getPlayerManager().getPlayerList()){var r=runtime(p);state(p).tick();if(!allowed(p)||r.dimension!=null&&r.dimension!=p.getWorld().getRegistryKey()){r.shield=0;r.shieldTicks=0;r.trapTicks=0;}if(r.shieldTicks>0&&--r.shieldTicks==0)r.shield=0;if(r.trapTicks>0){r.trapTicks--;if(server.getTicks()%10==0){var w=p.getServerWorld();for(var e:w.getEntitiesByClass(LivingEntity.class,new Box(r.trap.add(-3,-1,-3),r.trap.add(3,3,3)),e->enemy(p,e)&&e.squaredDistanceTo(r.trap)<=9&&p.canSee(e)))e.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,15,1));for(int i=0;i<24;i++){double a=i*Math.PI/12;burst(w,r.trap.add(Math.cos(a)*3,.1,Math.sin(a)*3),SignType.YRDEN,1);}}}if(server.getTicks()%10==0)sync(p);}if(server.getTicks()%20==0){SignLedger.get(server).markDirty();CALM.entrySet().removeIf(e->e.getValue()+80<server.getOverworld().getTime());}});}
}
